{'code': "import qgis.utils
p = qgis.utils.plugins.get('geo_launcher')
info = {'plugin': type(p).__name__ if p else None}
attrs = {}
if p:
    for a in dir(p):
        if a.startswith('_'):
            continue
        try:
            v = getattr(p, a)
        except Exception:
            continue
        t = type(v).__name__
        if 'Dialog' in t or 'Dock' in t or 'Widget' in t or 'dialog' in a.lower() or 'dock' in a.lower() or 'dlg' in a.lower():
            attrs[a] = {'type': t, 'visible': getattr(v, 'isVisible', lambda: None)()}
info['attrs'] = attrs
info['methods'] = [a for a in dir(p) if 'dialog' in a.lower() or 'open' in a.lower() or 'run' == a]
result = info"}

{'code': "import qgis.utils
p = qgis.utils.plugins.get('geo_launcher')
d = getattr(p, '_dialog', None)
info = {'dialog': type(d).__name__ if d else None}
if d:
    info['visible'] = d.isVisible()
    info['isMinimized'] = d.isMinimized() if hasattr(d, 'isMinimized') else None
    info['windowState'] = str(d.windowState())
# open_dialog を呼んでから前面化
p.open_dialog()
d = getattr(p, '_dialog', None)
if d:
    d.show()
    d.raise_()
    d.activateWindow()
    if hasattr(d, 'setWindowState'):
        from qgis.PyQt.QtCore import Qt
        d.setWindowState(d.windowState() & ~Qt.WindowMinimized | Qt.WindowActive)
    info['after'] = {'visible': d.isVisible(), 'geometry': str(d.geometry())}
result = info"}
